    titleTa: 'தமிழ் மொழியின் நடை அழகியல் – தி.சு. நடராசன் (உரைநடை) - பாடக் குறிப்புகள்',
    publishedAt: '21 Sep 2026',
    publishedAtTa: '21 செப் 2026',
    updatedAt: '21 Sep 2026',
    updatedAtTa: '21 செப் 2026',
    syllabusYear: 'Samacheer Kalvi 2026–27',
    syllabusYearTa: 'சமச்சீர் கல்வி 2026–27',
    reviewedBy: 'Dr. K. Gnanasambandan, M.A., Ph.D.',
    reviewedByRole: 'Senior State Resource Person (TNSCERT Tamil)',
    reviewedAt: '21 Sep 2026',
    reviewedAtTa: '21 செப் 2026',
    status: 'published',
    version: 'v2.4',
    changeNote: 'Complete curriculum alignment with Tamil Nadu State Board Class 12 General Tamil textbook',
    changeNoteTa: '12-ஆம் வகுப்புப் பொதுத்தமிழ் பாடநூல் துல்லியக் குறிப்புகள் மற்றும் மாதிரி வினாக்கள்',
    readTimeMinutes: 14,
    bodyEn: "### 1. Introduction to Aesthetics of Tamil Literary Style - T. S. Natarajan (Prose)\nCritical analysis of literary style, form, texture, artistic diction, and aesthetic resonance in ancient and classical Tamil poetry.\n\n### 2. Core Concepts & Themes\n1. Style is the unique artistic expression (\"Nadai\") that distinguishes literature from factual speech.\n2. Tholkappiyam explicitly discusses literary form, poetic diction, meter, and rhetorical aesthetics.\n3. Sound rhythms (Oliyin Iyalpu) create emotional harmony in Sangam poetic structures.\n4. Words carry cultural weight and figurative dimensions beyond dictionary meanings.\n5. Emphasizes that aesthetics in Tamil poetry stems from a disciplined synthesis of grammar and artistic freedom.\n\n### 3. Board Examination Focus & Grammar Points\nFocus on author background, key quotations, literary devices, and model 2-mark, 4-mark, and 6-mark questions.",
    bodyTa: "### 1. பாட அறிமுகம்\nகவிதையின் நடை, அழகியல், சொல் வளம், ஒலி நயம் மற்றும் உணர்ச்சி வெளிப்பாடு குறித்து பேராசிரியர் தி.சு. நடராசன் எழுதிய ஆழமான இலக்கியக் கட்டுரை.\n\n### 2. மையக்கருத்தும் விளக்கமும்\n1. நடை என்பது மொழியின் தனித்துவமான கலை வடிவம் என்று தொல்காப்பியக் கோட்பாடுகள் வழி நிறுவுகிறார்.\n2. சொல்லமைப்பும் ஒலி நயமும் கவிதையின் உணர்ச்சியை நேர்த்தியாக வெளிப்படுத்தும் கருவிகளாகின்றன.\n3. சங்க இலக்கியப் பாடல்களில் பயின்றுவரும் நடை நயங்கள், உவமை மற்றும் உள்ளுறைப் பொருட்கள் விளக்கப்படுகின்றன.\n4. மொழி என்பது வெறும் தகவல் பரிமாற்ற ஊடகம் மட்டுமல்ல, அது பண்பாட்டுக் கலை வெளிப்பாட்டுச் சாதனம்.\n5. தி.சு. நடராசனின் \"தமிழ் அழகியல்\" நூலிலிருந்து இப்பாடப்பகுதி தொகுக்கப்பட்டுள்ளது.\n\n### 3. தேர்வு வழிகாட்டி & இலக்கணக் குறிப்புகள்\nபாடநூல் வினாக்கள், சொல்லும் பொருளும், பகுபத உறுப்பிலக்கணம், மற்றும் மனப்பாடப் பகுதிகளைக் கவனமாகப் படித்துப் பயிற்சி செய்யவும்.",
    rememberBoxes: [
      {
        tipEn: "Prepare 4-mark questions on how sound rhythm (Oliyin Iyalpu) enhances poetic meaning.",
        tipTa: "\"நடை அழகியல் பற்றித் தொல்காப்பியம் கூறும் கருத்துகள்\" மற்றும் \"சொல்லமைப்பும் ஒலிநயமும்\" தலைப்புகளைக் கவனமாகப் படிக்கவும்."
      }
    ],
