        tipEn: "Memorize the definition and explanation of Porul Vetrumai Ani with this verse.",
        tipTa: "பொருள் வேற்றுமை அணியின் இலக்கணத்தையும், இப்பாடல் எவ்வாறு அதற்குச் சான்றாகிறது என்பதையும் 4 மதிப்பெண்களுக்குத் தெளிவாக எழுதுக."
