    changeNote: 'Complete curriculum alignment with Tamil Nadu State Board Class 12 General Tamil textbook',
    changeNoteTa: '12-ஆம் வகுப்புப் பொதுத்தமிழ் பாடநூல் துல்லியக் குறிப்புகள் மற்றும் மாதிரி வினாக்கள்',
    readTimeMinutes: 12,
    bodyEn: "### 1. Introduction to Thamizhaai Ezhuthuvom - Error-free Tamil Writing (Grammar)\nComprehensive guide to avoiding orthographic errors, distinguishing between மயங்கொலி எழுத்துகள் (ண/ந/ன, ல/ழ/ள, ர/ற), and proper consonant clusters.\n\n### 2. Core Concepts & Themes\n1. Mayangoli letters: 8 characters (ண, ந, ன; ல, ழ, ள; ர, ற) often confused by students.\n2. Place of articulation determines correct usage of dental, retroflex, and alveolar consonants.\n3. Rules for consonants: வல்லினம் (க், ச், ட், த், ப், ற்) cannot be doubled after certain soft consonants.\n4. Proper word division preserves meaning and prevents ambiguity.\n5. Grammatical precision in writing ensures clear communication and board examination accuracy.\n\n### 3. Board Examination Focus & Grammar Points\nFocus on author background, key quotations, literary devices, and model 2-mark, 4-mark, and 6-mark questions.",
    bodyTa: "### 1. பாட அறிமுகம்\nமயங்கொலி எழுத்துப் பிழைகள் (ண, ந, ன; ல, ழ, ள; ர, ற) மற்றும் சொல் பிழைகளை நீக்கிப் பிழையின்றித் தமிழில் எழுதும் விதிமுறைகள்.\n\n### 2. மையக்கருத்தும் விளக்கமும்\n1. மயங்கொலி எழுத்துகள் மொத்தம் 8: ண, ந, ன; ல, ழ, ள; ர, ற.\n2. எழுத்துகள் பிறக்கும் இடங்களை உணர்ந்து ஒலித்தால் பிழைகளைத் தவிர்க்கலாம்.\n3. சொல்லின் முதலில் வரும் எழுத்துகள் மற்றும் இறுதியில் நிற்கும் மெய்யெழுத்துகளின் விதிகள்.\n4. ட, ற முன் ண, ன வருதல்: கண்டான், சென்றான் போன்ற இலக்கண விதிகள்.\n5. எழுத்துப்பிழை இன்றி எழுத இப்பாடம் வழிகாட்டுகிறது.\n\n### 3. தேர்வு வழிகாட்டி & இலக்கணக் குறிப்புகள்\nபாடநூல் வினாக்கள், சொல்லும் பொருளும், பகுபத உறுப்பிலக்கணம், மற்றும் மனப்பாடப் பகுதிகளைக் கவனமாகப் படித்துப் பயிற்சி செய்யவும்.",
    rememberBoxes: [
      {
        tipEn: "Practice identifying and correcting Mayangoli errors in sentences.",
        tipTa: "மயங்கொலி எழுத்துகளான ண-ந-ன, ல-ழ-ள, ர-ற வேறுபாடுகளைக் காட்டும் சொற்களைப் பட்டியலிட்டுப் பயிற்சி செய்க."
      }
    ],
