        tipEn: "Key question on causes of natural disasters and traditional water harvesting systems.",
        tipTa: "\"இயற்கைச் சமநிலையைப் பேண நாம் செய்ய வேண்டிய பணிகள் யாவை?\" என்ற வினாவிற்குரிய குறிப்புகளைத் தொகுத்துக் கொள்க."
