        tipEn: "Understand how the poet uses imagery of drying walls and sunlight.",
        tipTa: "மழைக்குப் பின்னான நகரத்தின் மாற்றத்தை அய்யப்ப மாதவன் எவ்வாறு வர்ணிக்கிறார் என்பதை 2 மற்றும் 4 மதிப்பெண்களுக்குப் படிக்கவும்."
