    changeNoteTa: '12-ஆம் வகுப்புப் பொதுத்தமிழ் பாடநூல் துல்லியக் குறிப்புகள் மற்றும் மாதிரி வினாக்கள்',
    readTimeMinutes: 14,
    bodyEn: "### 1. Introduction to Nedunalvaadai - Nakkirar (Sangam Classical Poetry)\nSangam classic from Pathupattu portraying the chilling north winter wind (Vaadai) freezing herds, birds, and citizens, contrasted with the queen longing in her palace.\n\n### 2. Core Concepts & Themes\n1. Composed by Sangam poet Nakkirar, part of the Ten Idylls (Pathupattu).\n2. Hero: Pandiyan Nedunchezhian (victor of Thalaiyalanganam).\n3. Title significance: Long sorrowful winter wind (Nedum Vaadai) to the grieving queen, but good victorious wind (Nal Vaadai) to the king fulfilling royal duty.\n4. Depicts freeze of cattle shunning green grass and monkeys shivering with cold.\n5. Masterpiece of realistic Sangam nature portrayal and Akam-Puram synthesis.\n\n### 3. Board Examination Focus & Grammar Points\nFocus on author background, key quotations, literary devices, and model 2-mark, 4-mark, and 6-mark questions.",
    bodyTa: "### 1. பாட அறிமுகம்\nபத்துப்பாட்டு நூல்களுள் ஒன்றான நெடுநல்வாடை. வாடைக் காற்றின் குளிரால் நடுங்கும் விலங்குகள், ஆயர்கள் மற்றும் போர்க்களத்தில் அரசனும், அரண்மனையில் பிரிவால் வருந்தும் அரசியும் விவரிக்கப்படும் சங்க இலக்கியம்.\n\n### 2. மையக்கருத்தும் விளக்கமும்\n1. பத்துப்பாட்டு நூல்களுள் ஒன்று; 188 அடிகளைக் கொண்ட ஆசிரியப்பாவால் ஆனது; பாடியவர் நக்கீரர்.\n2. பாட்டுடைத் தலைவன்: தலையாலங்கானத்துச் செருவென்ற பாண்டியன் நெடுஞ்செழியன்.\n3. பெயர் விளக்கம்: தலைவனைப் பிரிந்த தலைவிக்கு நெடுவாடையாகவும், போர்க்களத்தில் வெற்றி காணும் தலைவனுக்கு நல்வாடையாகவும் அமைந்ததால் \"நெடுநல்வாடை\".\n4. குளிரினால் மாடுகள் மேய்ச்சலை மறக்கின்றன; குரங்குகள் நடுங்குகின்றன; பறவைகள் மரங்களிலிருந்து விழுகின்றன.\n5. முல்லை நிலத்து ஆயர்கள் கைகளில் கொள்ளி நெருப்பைக் கொண்டு உடலைச் சூடேற்றும் காட்சி நெஞ்சை அள்ளுகிறது.\n\n### 3. தேர்வு வழிகாட்டி & இலக்கணக் குறிப்புகள்\nபாடநூல் வினாக்கள், சொல்லும் பொருளும், பகுபத உறுப்பிலக்கணம், மற்றும் மனப்பாடப் பகுதிகளைக் கவனமாகப் படித்துப் பயிற்சி செய்யவும்.",
    rememberBoxes: [
      {
        tipEn: "Explain the title justification \"Nedunalvaadai\" (Nedum + Nal + Vaadai).",
        tipTa: "\"நெடுநல்வாடை - பெயர் அமைப்புக் காரணத்தை விளக்குக\" என்ற வினா பொதுத்தேர்வுக்கு மிக முக்கியமானது."
      }
    ],
