        tipEn: "Character sketch of Maruthan and the theme of collective social action.",
        tipTa: "\"மருதனின் தியாகமும் கூட்டு முயற்சியும் ஊரைக் காப்பாற்றிய விதம்\" குறித்து 6 மதிப்பெண் வினாவிற்குத் தயார் செய்க."
