    status: 'published',
    version: 'v2.4',
    changeNote: 'Complete curriculum alignment with Tamil Nadu State Board Class 12 General Tamil textbook',
    changeNoteTa: '12-ஆம் வகுப்புப் பொதுத்தமிழ் பாடநூல் துல்லியக் குறிப்புகள் மற்றும் மாதிரி வினாக்கள்',
    readTimeMinutes: 12,
    bodyEn: "### 1. Introduction to Naalvagai Poruthangal - Gender, Number, Person (Grammar)\nSyntactic concord in Tamil: Agreement between subject and predicate in terms of Thinai (Class), Paal (Gender), En (Number), and Idam (Person).\n\n### 2. Core Concepts & Themes\n1. Fourfold grammatical concord: Thinai (உயர்திணை / அஃறிணை), Paal (5 types), En (ஒருமை / பன்மை), Idam (தன்மை / முன்னிலை / படர்க்கை).\n2. Subject and verb must match in gender and number (e.g., கண்ணன் வந்தான், மாடுகள் மேய்ந்தன).\n3. Common discrepancies occur in honorific singular and plural usage (e.g., வந்தார் vs வந்தார்கள்).\n4. Semantic concord ensures grammatical elegance and logical coherence.\n5. Essential for sentence correction questions in Higher Secondary examinations.\n\n### 3. Board Examination Focus & Grammar Points\nFocus on author background, key quotations, literary devices, and model 2-mark, 4-mark, and 6-mark questions.",
    bodyTa: "### 1. பாட அறிமுகம்\nஎழுவாய்க்கும் பயனிலைக்கும் இடையே திணை, பால், எண், இடம் ஆகிய நால்வகைப் பொருத்தங்கள் அமைய வேண்டிய தொடரியல் இலக்கண விதிகள்.\n\n### 2. மையக்கருத்தும் விளக்கமும்\n1. நால்வகைப் பொருத்தங்கள்: திணை (உயர்திணை, அஃறிணை), பால் (ஐம்பால்), எண் (ஒருமை, பன்மை), இடம் (மூவிடம்).\n2. எழுவாய்க்கு ஏற்ப பயனிலை அமைதல் வேண்டும்: சான்றாக, செல்வி பாடினாள் (பெண்பால் ஒருமை).\n3. மரியாதை பன்மை மற்றும் பொதுப்பெயர் பயன்பாடுகளில் ஏற்படும் வழுக்களைக் களையும் முறை.\n4. பால் காட்டும் விகுதிகள் மற்றும் பயனிலைப் பொருத்தங்கள்.\n5. பொதுத்தேர்வில் பிழைநீக்கி எழுதுதல் வினாக்களுக்கு இது மிக இன்றியமையாத பகுதி.\n\n### 3. தேர்வு வழிகாட்டி & இலக்கணக் குறிப்புகள்\nபாடநூல் வினாக்கள், சொல்லும் பொருளும், பகுபத உறுப்பிலக்கணம், மற்றும் மனப்பாடப் பகுதிகளைக் கவனமாகப் படித்துப் பயிற்சி செய்யவும்.",
