    readTimeMinutes: 14,
    bodyEn: "### 1. Introduction to Thamizhar Kudumba Murai - Bhaktavatsala Bharathi (Prose)\nAnthropological study tracing the evolution of family structure, kinship systems, matriarchy, and social bonds in ancient Tamil civilization.\n\n### 2. Core Concepts & Themes\n1. Anthropologist Bhaktavatsala Bharathi analyzes Tamil kinship from Sangam texts.\n2. Highlights early mother-centered (matrilineal) social units in Tamil society.\n3. Sangam terms \"Il\", \"Manai\", and \"Kudumbam\" denote progressive stages of household evolution.\n4. Joint family values promoted mutual support and social security.\n5. Demonstrates the antiquity and institutional maturity of ancient Tamil domestic life.\n\n### 3. Board Examination Focus & Grammar Points\nFocus on author background, key quotations, literary devices, and model 2-mark, 4-mark, and 6-mark questions.",
    bodyTa: "### 1. பாட அறிமுகம்\nசங்க காலத் தமிழரின் தாய்வழி மற்றும் தந்தைவழி குடும்ப அமைப்புகள், மணக்கொடை, மற்றும் சுற்றத்தாரின் உறவுமுறைகளை மானிடவியல் நோக்கில் விளக்கும் அரிய கட்டுரை.\n\n### 2. மையக்கருத்தும் விளக்கமும்\n1. மானிடவியல் ஆய்வாளர் பக்தவத்சல பாரதியின் \"தமிழர் மானிடவியல்\" நூலில் இருந்து எடுக்கப்பட்டது.\n2. சங்க காலத்தில் தாய்வழிச் சமூக அமைப்பும், தாய்வழிக் குடும்ப முறையுமே முதன்மையாக நிலவின.\n3. இல், மனை, குரம்பை போன்ற சொற்கள் குடும்ப அமைப்பின் பரிணாம வளர்ச்சியைக் காட்டுகின்றன.\n4. குடும்பம் என்ற சொல் முதன்முதலில் திருக்குறளில்தான் பயின்றுவந்துள்ளது (குறள் 1029).\n5. தமிழரின் கூட்டுக்குடும்ப வாழ்வியல் பண்புகள் உலகிற்கே சிறந்த வழிகாட்டலாகும்.\n\n### 3. தேர்வு வழிகாட்டி & இலக்கணக் குறிப்புகள்\nபாடநூல் வினாக்கள், சொல்லும் பொருளும், பகுபத உறுப்பிலக்கணம், மற்றும் மனப்பாடப் பகுதிகளைக் கவனமாகப் படித்துப் பயிற்சி செய்யவும்.",
    rememberBoxes: [
      {
        tipEn: "Note where the word \"Kudumbam\" first appeared in Tamil literature (Thirukkural).",
        tipTa: "\"குடும்பம் என்ற சொல் உருவான வரலாறு மற்றும் தாய்வழி முறை\" பற்றி 4 மதிப்பெண்களுக்குத் தயார் செய்க."
      }
    ],
