    titleTa: 'பண்டைய காலத்துப் பள்ளிக்கூடங்கள் – உ.வே. சாமிநாதையர் (உரைநடை) - பாடக் குறிப்புகள்',
    publishedAt: '21 Sep 2026',
    publishedAtTa: '21 செப் 2026',
