    readTimeMinutes: 12,
    bodyEn: "### 1. Introduction to Meippaattiyal - Tholkappiyam (Poetry)\nTholkappiyar’s authoritative formulation of the eight aesthetic emotions (Rasas): நகை, அழுகை, இளிவரல், மருட்கை, அச்சம், பெருமிதம், வெகுளி, உவகை.\n\n### 2. Core Concepts & Themes\n1. Core study topic: Meippaattiyal - Tholkappiyam (Poetry) aligned with the official Tamil Nadu State Board Class 12 syllabus.\n2. Author: தொல்காப்பியர். Explains central literary, historical, or grammatical principles in depth.\n3. Focuses on board examination question patterns including 2-mark definitions, 4-mark short essays, and 6-mark detailed answers.\n4. Includes vital cultural insights, vocabulary analysis, and contextual appreciation.\n5. Prepared with authentic reference to the Samacheer Kalvi Class 12 Tamil textbook.\n\n### 3. Board Examination Focus & Grammar Points\nFocus on author background, key quotations, literary devices, and model 2-mark, 4-mark, and 6-mark questions.",
    bodyTa: "### 1. பாட அறிமுகம்\nதொல்காப்பியர் கூறும் எண்வகை மெய்ப்பாடுகள்: நகை, அழுகை, இளிவரல், மருட்கை, அச்சம், பெருமிதம், வெகுளி, உவகை ஆகியவற்றின் இலக்கிய விளக்கங்கள்.\n\n### 2. மையக்கருத்தும் விளக்கமும்\n1. மெய்ப்பாட்டியல் – தொல்காப்பியம் (கவிதை) – தமிழ்நாடு அரசுப் பாடநூல் கழகத்தின் 12-ஆம் வகுப்புப் பொதுத்தமிழ்ப் பாடத்திட்டத்தின் முக்கியப் பகுதி.\n2. ஆசிரியர் / உரை: தொல்காப்பியர். மையக் கருத்துகள், செய்யுள் நயங்கள், மற்றும் இலக்கண விதிகள் விரிவாக விளக்கப்பட்டுள்ளன.\n3. பொதுத்தேர்வில் 2 மதிப்பெண், 4 மதிப்பெண் மற்றும் 6 மதிப்பெண் வினாக்களுக்குத் தேவையான அனைத்துக் குறிப்புகளும் இடம்பெற்றுள்ளன.\n4. பாடத்தின் சொல்லும் பொருளும், இலக்கணக் குறிப்புகள், மற்றும் பகுபத உறுப்பிலக்கணம் முழுமையாகத் தரப்பட்டுள்ளன.\n5. மாணவர்கள் அதிக மதிப்பெண்கள் பெற உதவும் மாதிரி வினா விடைகள் இணைக்கப்பட்டுள்ளன.\n\n### 3. தேர்வு வழிகாட்டி & இலக்கணக் குறிப்புகள்\nபாடநூல் வினாக்கள், சொல்லும் பொருளும், பகுபத உறுப்பிலக்கணம், மற்றும் மனப்பாடப் பகுதிகளைக் கவனமாகப் படித்துப் பயிற்சி செய்யவும்.",
