        tipEn: "Review author profile of வெ. இறையன்பு இ.ஆ.ப and practice board model questions for this chapter.",
        tipTa: "வெ. இறையன்பு இ.ஆ.ப பற்றிய குறிப்புகளையும், பாடத்தின் பின்னுள்ள வினாக்களையும் முழுமையாகப் படித்துப் பயிற்சி செய்க."
