      "கரிசல் மண்ணின் வறட்சியும், ஏழை விவசாயிகளின் நில உரிமைப் போராட்டமும் விவரிக்கப்படுகிறது.",
      "அண்ணன் தம்பிக்குள் வரும் சிறு மனக்கசப்புகள் நிலத்தை விற்க நேரிடும்போது பாசமாக மாறும் காட்சி.",
