  c12_tam_i4_ch1: {
    id: 'sum_c12_tam_i4_ch1',
    chapterId: 'c12_tam_i4_ch1',
    lastUpdatedAt: '21 Sep 2026',
    lastUpdatedAtTa: '21 செப் 2026',
    keyPointsEn: [
      "Core study topic: Pandaiya Kaalathu Pallikkoodangal - U.Ve.Sa (Prose) aligned with the official Tamil Nadu State Board Class 12 syllabus.",
      "Author: உ.வே. சாமிநாதையர். Explains central literary, historical, or grammatical principles in depth.",
      "Focuses on board examination question patterns including 2-mark definitions, 4-mark short essays, and 6-mark detailed answers.",
      "Includes vital cultural insights, vocabulary analysis, and contextual appreciation.",
      "Prepared with authentic reference to the Samacheer Kalvi Class 12 Tamil textbook."
],
    keyPointsTa: [
      "பண்டைய காலத்துப் பள்ளிக்கூடங்கள் – உ.வே. சாமிநாதையர் (உரைநடை) – தமிழ்நாடு அரசுப் பாடநூல் கழகத்தின் 12-ஆம் வகுப்புப் பொதுத்தமிழ்ப் பாடத்திட்டத்தின் முக்கியப் பகுதி.",
      "ஆசிரியர் / உரை: உ.வே. சாமிநாதையர். மையக் கருத்துகள், செய்யுள் நயங்கள், மற்றும் இலக்கண விதிகள் விரிவாக விளக்கப்பட்டுள்ளன.",
      "பொதுத்தேர்வில் 2 மதிப்பெண், 4 மதிப்பெண் மற்றும் 6 மதிப்பெண் வினாக்களுக்குத் தேவையான அனைத்துக் குறிப்புகளும் இடம்பெற்றுள்ளன.",
      "பாடத்தின் சொல்லும் பொருளும், இலக்கணக் குறிப்புகள், மற்றும் பகுபத உறுப்பிலக்கணம் முழுமையாகத் தரப்பட்டுள்ளன.",
      "மாணவர்கள் அதிக மதிப்பெண்கள் பெற உதவும் மாதிரி வினா விடைகள் இணைக்கப்பட்டுள்ளன."
],
    simpleExplanationEn: "Historical overview of ancient gurukulam, pial schools, palm-leaf writing, and memory training in Tamil Nadu.",
    simpleExplanationTa: "திண்ணைப் பள்ளிக்கூடங்கள், ஏட்டுச் சுவடிகள், எழுத்தாணி மற்றும் பண்டைய தமிழரின் கல்வி முறைகளைத் தமிழ்த்தாத்தா உ.வே.சா விவரிக்கும் கட்டுரை."
  },
