      "திருக்குறள் – வாழ்வியல் அறநெறிகள் பகுதி 2 (திருவள்ளுவர்) – தமிழ்நாடு அரசுப் பாடநூல் கழகத்தின் 12-ஆம் வகுப்புப் பொதுத்தமிழ்ப் பாடத்திட்டத்தின் முக்கியப் பகுதி.",
