            "correctAnswer": "Porul Vetrumai Ani",
            "explanationEn": "The verse illustrates Porul Vetrumai Ani by showing similarities between Sun and Tamil, then demonstrating Tamil's unique superiority.",
            "explanationTa": "கதிரவனுக்கும் தமிழுக்கும் உள்ள ஒற்றுமையைக் கூறி, பின் தமிழின் தனித்தன்மையை உயர்த்தி வேற்றுமைப்படுத்திக் காட்டுவதால் இது பொருள் வேற்றுமை அணி."
