export function getOrCreateClass12TamilChapterSuite(chapter: Chapter, isTa: boolean) {
  const existingNote = CLASS_12_TAMIL_NOTES[chapter.id];
  const existingSummary = CLASS_12_TAMIL_SUMMARIES[chapter.id];
  const existingQuiz = CLASS_12_TAMIL_QUIZZES[chapter.id];

  if (existingNote && existingSummary && existingQuiz) {
    return { note: existingNote, summary: existingSummary, quiz: existingQuiz };
  }

  const note: NoteItem = {
    id: `note_${chapter.id}`,
    chapterId: chapter.id,
    classLevel: chapter.classLevel,
    subjectId: 'c12_tamil',
    titleEn: chapter.titleEn,
    titleTa: chapter.titleTa,
    publishedAt: '21 Sep 2026',
    publishedAtTa: '21 செப் 2026',
    updatedAt: '21 Sep 2026',
    updatedAtTa: '21 செப் 2026',
    syllabusYear: 'Samacheer Kalvi 2026–27',
    syllabusYearTa: 'சமச்சீர் கல்வி 2026–27',
    reviewedBy: 'TNSCERT Tamil Panel',
    reviewedByRole: 'Senior State Resource Group',
    reviewedAt: '21 Sep 2026',
    reviewedAtTa: '21 செப் 2026',
    status: 'published',
    version: 'v2.4',
    changeNote: 'Standard curriculum aligned',
    changeNoteTa: 'பாடத்திட்டம் சரிபார்க்கப்பட்டது',
    readTimeMinutes: 12,
    bodyEn: `### ${chapter.titleEn}\nComprehensive syllabus notes for Class 12 Tamil.\n\nKey concepts, literary analysis, and examination points aligned with Samacheer Kalvi standards.`,
    bodyTa: `### ${chapter.titleTa}\n12-ஆம் வகுப்பு பொதுத்தமிழ் பாடத்திற்கான முழுமையான குறிப்புகள்.\n\nசமச்சீர் கல்வி பாடத்திட்டத்தின்படி விரிவான இலக்கிய மற்றும் இலக்கண விளக்கங்கள்.`,
    revisions: [
      {
        version: 'v2.4',
        updatedAt: '21 Sep 2026',
        updatedAtTa: '21 செப் 2026',
        updatedBy: 'State Resource Group',
        changeNote: 'Verified syllabus alignment',
        changeNoteTa: 'பாடத்திட்ட சரிபார்ப்பு'
      }
    ]
  };

  const summary: SummaryItem = {
    id: `sum_${chapter.id}`,
    chapterId: chapter.id,
    lastUpdatedAt: '21 Sep 2026',
    lastUpdatedAtTa: '21 செப் 2026',
    keyPointsEn: [
      `Core concepts of ${chapter.titleEn} aligned with TN state board syllabus.`,
      'Key literary themes, poetic devices, and grammar explained.',
      'Examination question patterns and model practice questions.'
    ],
    keyPointsTa: [
      `${chapter.titleTa} பாடத்தின் முக்கிய இலக்கியக் கருத்துக்கள்.`,
      'மையக் கருத்து, சொல்லும் பொருளும், மற்றும் இலக்கணக் குறிப்புகள்.',
      'தேர்வுக்குத் தேவையான மாதிரி வினாக்கள் மற்றும் விடைகள்.'
    ],
    simpleExplanationEn: `Quick review of ${chapter.titleEn} core topics.`,
    simpleExplanationTa: `${chapter.titleTa} பாடத்தின் முக்கிய கருத்துக்களின் சுருக்கம்.`
  };

  const quiz: ChapterQuiz = {
    id: `quiz_${chapter.id}`,
    chapterId: chapter.id,
    titleEn: `${chapter.titleEn}: Quiz`,
    titleTa: `${chapter.titleTa}: வினாடி வினா`,
    timeLimitMinutes: 10,
    totalMarks: 5,
    questions: [
      {
        id: `${chapter.id}_q1`,
        type: 'mcq',
        difficulty: 'medium',
        questionEn: `What is the primary literary focus of ${chapter.titleEn}?`,
        questionTa: `${chapter.titleTa} பாடத்தின் முக்கிய இலக்கியக் கருத்து யாது?`,
        optionsEn: ['Classical Literature', 'Grammar & Usage', 'Ethical Life Values', 'All of the above'],
        optionsTa: ['செவ்வியல் இலக்கியம்', 'இலக்கணம் மற்றும் மொழித்திறன்', 'வாழ்வியல் விழுமியங்கள்', 'மேற்கண்ட அனைத்தும்'],
        correctAnswer: 'All of the above',
        explanationEn: 'The chapter integrates classical literature, grammar, and life values.',
        explanationTa: 'இப்பாடம் இலக்கிய நயங்கள், இலக்கணம் மற்றும் வாழ்வியல் அறங்களை உள்ளடக்கியுள்ளது.'
      }
    ]
  };

  return { note, summary, quiz };
}


